function inverse(obj){
  let retobj = {};
  for(var key in obj){
    retobj[obj[key]] = key;
  }
  return retobj;
}

flow.set('reverse_endpoint',{},'memoryOnly');
flow.set('reverse_endpoint',inverse(global.get('kernel.endpoint','default')),'memoryOnly');

msg.payload = '';
return msg;

if (typeof msg.hmi === 'undefined') {
    msg.hmi = {
        'tab':99,
        'page':'',
        'id':'',
        'login':'',
        'level':'',
        'plant':''
    };
}

if (typeof msg.hmi.lang !== 'string') {
    msg.hmi.lang = 'en';
}

if (typeof msg.tab === 'number' && typeof msg.name === 'string') {
    msg.hmi.tab = msg.tab;
    msg.hmi.page = msg.name;
    delete msg.tab;
    delete msg.name;
}

if (typeof msg._client?.socketId === 'string') {
    let browser_lang = global.get('browser["' + msg._client.socketId + '"]["lang"]', 'memoryOnly');
    if (typeof browser_lang === 'string') {
        msg.hmi.lang = browser_lang;
    }
    msg.hmi.id = msg._client.socketId;

    let user = global.get('user["' + msg.hmi.id + '"]', 'memoryOnly');
    if (typeof user === 'object') {
        msg.hmi = Object.assign({}, msg.hmi, user);
    }
}

msg.hmi.time = Date.now();

return msg;

let entity = msg.row.equipment + '|run';
let state = global.get('kernel.state["' + entity + '"]', 'default');

if (typeof state === 'number' && state === 1) {
    return [null, msg];
} else {
    return [msg, null];
}

let newMsg = {
    'kernel':{},
    'topic':'',
    'payload':''
};

let time = global.get('kernel.app.watchdog', 'default')||120;
let limit = Date.now() - (time * 1000);

let devices = global.get('kernel.device', 'default');
if (typeof devices === 'object') {
    for (const device in devices) {

        let watchdog = global.get('kernel.watchdog["' + device + '"]', 'default')||0;

        newMsg.kernel = {
            'type':'device',
            'entity':device,
            'value': watchdog < limit ? 0:1,
            'loop':false
        };

        node.send(newMsg);
    }
}

return;

delete msg.qos;
delete msg.retain;

/* check kernel message */
if (typeof msg.kernel === 'object'
    && typeof msg.kernel.type === 'string'
    && typeof msg.kernel.entity === 'string'
    && typeof msg.kernel.value !== 'undefined'
    && typeof msg.kernel.loop === 'boolean'
) {
    /* deletion requested */
    if (typeof msg.kernel.delete === 'boolean' && msg.kernel.delete === true) {
        global.set('kernel["' + msg.kernel.type + '"]["' + msg.kernel.entity + '"]', undefined, 'default');
    } else {
        let current = global.get('kernel["' + msg.kernel.type + '"]["' + msg.kernel.entity + '"]', 'default');
        /* new value is not the same as existing */
        if (current !== msg.kernel.value) {
            //msg.kernel.loop = false;
            /* update kernel value */
            global.set('kernel["' + msg.kernel.type + '"]["' + msg.kernel.entity + '"]', msg.kernel.value, 'default');
        }

        /* do loop */
        if (msg.kernel.loop === false) {
            return {
                'topic':'',
                'payload':'',
                'kernel':msg.kernel
            };
        }
    }
}

return;

if (msg.kernel.type === 'state') {
    let endpoint = flow.get('reverse_endpoint["' + msg.kernel.entity + '"]', 'memoryOnly');
    if (typeof endpoint === 'string') {
        let esplit = endpoint.split("|");
        msg.kernel.model = esplit[0];
        msg.kernel.device = esplit[1];
        msg.kernel.endpoint = esplit[2];

        let csplit = msg.kernel.entity.split("|");
        msg.kernel.equipment = csplit[0];
        msg.kernel.component = csplit[1];

        return msg;
    }
}

return;

if (msg.kernel.component !== 'cycle' || msg.kernel.value > 0) {
    msg.measurement = msg.kernel.equipment;
    msg.payload = [{[msg.kernel.component]: msg.kernel.value }];

    delete msg.endpoint;
    delete msg.kernel;

    return msg;
}

return;

msg.measurement = msg.kernel.entity;
msg.payload = [{'watchdog': msg.kernel.value }];

delete msg.kernel;

return msg;

if (typeof msg.login === 'string' && msg.login !== "" && typeof msg.pass === 'string' && msg.pass !== "") {
    let hash = global.get('auth["' + msg.login + '"]["pass"]', 'memoryOnly');
    if (typeof hash === 'string') {
        msg.hash = hash;

        return msg;
    }
}

return msg;

/* Limit to 6 hours */
let limit = Date.now() - (6*60*60*1000);
msg.topic = limit;

let users = global.get('user', 'memoryOnly');
if (typeof users === 'object') {
    for (const user in users) {
        if (typeof global.get('auth["' + users[user]["login"] + '"]["level"]', 'memoryOnly') !== 'string' 
        || users[user]["time"] < limit 
        || (typeof msg.login === 'string' && msg.login === users[user]["login"])
        ) {
            global.set('user["' + user + '"]', undefined, 'memoryOnly');
            msg.payload = user;
            node.send(msg);
        }
    }
}

msg.payload = 'cleaned';

return msg;

let newMsg = {
    'topic':'',
    'payload':'',
    'kernel':{
        'type':'',
        'entity':'',
        'value':'',
        'loop':true,
        'delete':false
    }
};

/* Check if payload is well formed */
if (typeof msg.payload?.app?.vendor === 'string') {
    /* Delete current kernel */
    //global.set('kernel', newMsg.kernel, 'default');

    for (const type in msg.payload) {
        newMsg.kernel.type = type;

        for (const entity in msg.payload[type]) {
            newMsg.kernel.entity = entity;
            newMsg.kernel.value = msg.payload[type][entity];

            node.send(newMsg);
        }
    }
}

msg.payload = 'Lecture du fichier de sauvegarde terminée';

return msg;

if (global.get('kernel.app.frommqtt', 'default') === true && msg.payload !== '') {
    let tsplit = msg.topic.split('/');
    if (tsplit.length === 3 && typeof global.get('kernel["' + tsplit[1] + '"]["' + tsplit[2] + '"]', 'default') !== 'undefined') {
        return {
            'topic':'',
            'payload':'',
            'kernel':{
                'type':tsplit[1],
                'entity':tsplit[2],
                'value':msg.payload,
                'loop':true
            }
        }
    }
}

return;

if (msg.payload === 'disconnect') {
    global.set('user["' + msg.hmi.id + '"]', undefined, 'memoryOnly');
    return;
}

if (msg.payload !== 'change' && msg.payload !== 'connect') {
    return;
}

if (msg.payload === 'connect') {
    msg.tab = global.get('describe.pages.auth.tab', 'memoryOnly');
    msg.name = global.get('describe.pages.auth.name', 'memoryOnly');
}

msg.menus = {};
msg.titles = {};
msg.payload = {
    'pages':{
        'show':[],
        'hide':[]
    }
};

let pages = global.get('describe.pages', 'memoryOnly');
if (typeof pages !== 'object') {
    return;
}

let allowed = false;
let s = 0;
let h = 0;
for (const page in pages) {
    if (typeof pages[page]['level'][msg.hmi.level] === 'boolean') {
        if (pages[page]['level'][msg.hmi.level] === true) {
            msg.menus[page] = true;
            msg.payload.pages.show[s++] = pages[page]['name'];
        } else {
            msg.menus[page] = false;
            msg.payload.pages.hide[h++] = pages[page]['name'];
        }
    } else {
        if (global.get('describe.pages.auth.tab', 'memoryOnly') === pages[page]['tab']) {
            msg.menus[page] = true;
            msg.payload.pages.show[s++] = pages[page]['name'];
        } else {
            msg.menus[page] = false;
            msg.payload.pages.hide[h++] = pages[page]['name'];
        }
    }
    msg.titles[page] = msg.dictionary.option_page[page];

    if (pages[page]['tab'] === msg.hmi.tab) {
        msg.page_title = msg.dictionary.option_page[page];
        msg.page_lang = msg.dictionary.lang;
    }

    if (pages[page]['tab'] === msg.hmi.tab && pages[page]['level'][msg.hmi.level] === true) {
        allowed = true;
    }
}

if (allowed === false) {
    msg.hmi.tab = global.get('describe.pages.auth.tab', 'memoryOnly');
    msg.hmi.page = global.get('describe.pages.auth.name', 'memoryOnly');
}

return msg;

if (msg.payload !== '' && typeof global.get('describe.pages["' + msg.payload + '"]["name"]', 'memoryOnly') === 'string') {
    msg.tab = global.get('describe.pages["' + msg.payload + '"]["tab"]', 'memoryOnly');
    msg.name = global.get('describe.pages["' + msg.payload + '"]["name"]', 'memoryOnly');
    msg.payload = msg.name;

    return msg;
}

let browser = {
    'lang':msg.payload,
    'time':Date.now()
}
global.set('browser["' + msg._client.socketId + '"]', browser, 'memoryOnly');

let time = Date.now() - 60000;
let browsers = global.get('browser', 'memoryOnly');
if (typeof browsers === 'object') {
    for (const browser in browsers) {
        if (browsers[browser]['time'] < time) {
            global.set('browser["' + browser + '"]', undefined, 'memoryOnly');
        }
    }
}

return;

if (typeof global.get('kernel.team','default') === 'object'
    && typeof global.get('kernel.period','default') === 'object'
    && typeof global.get('kernel.state','default') === 'object'
) {
    flow.set('teams', {}, 'memoryOnly');
    flow.set('periods', {}, 'memoryOnly');
    flow.set('exists', {}, 'memoryOnly');
    flow.set('pilots', {}, 'memoryOnly');

    return {
        'topic':'',
        'payload':'',
        'row':{}
    };
}

return;

const options = Object.values(msg.payload)
msg.options = options;
return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'plant'
}];

let plants = global.get('kernel.plant', 'default');
let i = 1;

if (typeof plants === 'object') {
    for (const plant in plants) {
        msg.options[i++] = {
            'label':plants[plant] + ' (' + plant + ')',
            'value':plant,
            'dropdown':'plant'
        }
    }
}

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'line'
}];

let lines = global.get('kernel.line', 'default');
let i = 1;

if (typeof lines === 'object') {
    for (const line in lines) {
        let line_plant = global.get('kernel.lines["' + line + '"]', 'default');
        if (typeof msg.limit_plant === 'undefined' || msg.limit_plant === line_plant) {
            msg.options[i++] = {
                'label':lines[line] + ' (' + line + ')',
                'value':line,
                'dropdown':'line'
            }
        }
    }
}

delete msg.limit_plant;

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'equipment'
}];

let equipments = global.get('kernel.equipment', 'default');
let i = 1;

if (typeof equipments === 'object') {
    for (const equipment in equipments) {
        let equipment_line = global.get('kernel.equipments["' + equipment + '"]', 'default');
        if (typeof msg.limit_line === 'undefined' || msg.limit_line === equipment_line) {
            msg.options[i++] = {
                'label':equipments[equipment] + ' (' + equipment + ')',
                'value':equipment,
                'dropdown':'equipment'
            }
        }
    }
}

delete msg.limit_line;

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'model'
}];

let models = global.get('describe.model', 'memoryOnly');
let i = 1;

if (typeof models === 'object') {
