}

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'team'
}];

let teams = msg.dictionary?.option_team;
let i = 1;

if (typeof teams === 'object') {
    for (const team in teams) {
        msg.options[i++] = {
            'label':teams[team] + ' (' + team + ')',
            'value':team,
            'dropdown':'team'
        }
    }
}

msg.nosort = true;

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'resolution'
}];

let resolutions = msg.dictionary?.option_resolution;
let i = 1;

if (typeof resolutions === 'object') {
    for (const resolution in resolutions) {
        msg.options[i++] = {
            'label': resolutions[resolution],
            'value': resolution,
            'dropdown':'resolution'
        }
    }
}

msg.nosort = true;

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'level'
}];

let levels = msg.dictionary?.option_level;
let i = 1;

if (typeof levels === 'object') {
    for (const level in levels) {
        msg.options[i++] = {
            'label': levels[level],
            'value': level,
            'dropdown':'level'
        }
    }
}

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'lang'
}];

let langs = msg.dictionary?.option_lang;
let i = 1;

if (typeof langs === 'object') {
    for (const lang in langs) {
        msg.options[i++] = {
            'label': langs[lang] + ' (' + lang + ')',
            'value': lang,
            'dropdown':'lang'
        }
    }
}

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'login'
}];

let logins = global.get('auth', 'memoryOnly');
let i = 1;

if (typeof logins === 'object') {
    for (const login in logins) {
        msg.options[i++] = {
            'label':login,
            'value':login,
            'dropdown':'login'
        }
    }
}

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'alert'
}];

let alerts = global.get('kernel.alert', 'default');
let i = 1;

if (typeof alerts === 'object') {
    for (const alert in alerts) {
        const split = alert.split("|");
        if (typeof msg.limit_equipment === 'undefined' || msg.limit_equipment === split[0]) {
            let name = msg.dictionary.option_component[split[1]];
            msg.options[i++] = {
                'label':name + ' (' + alert + ')',
                'value':alert,
                'dropdown':'alert'
            }
        }
    }
}

delete msg.limit_equipment;

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'component'
}];

let components = msg.dictionary?.option_component;
let i = 1;

if (typeof components === 'object') {
    for (const component in components) {
        if (typeof msg.limit_component === 'undefined' || component.match((new RegExp('^(' + msg.limit_component + ')$'))) !== null) {
            msg.options[i++] = {
                'label': components[component] + ' (' + component + ')',
                'value': component,
                'dropdown':'component'
            }
        }
    }
}

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'endpoint'
}];

let i = 1;

if (typeof msg.limit_model !== 'undefined') {
    let endpoints = global.get('describe.endpoint["' + msg.limit_model + '"]', 'memoryOnly');
    if (typeof endpoints === 'object') {
        for (const endpoint in endpoints) {
            msg.options[i++] = {
                'label': endpoints[endpoint] + ' (' + endpoint + ')',
                'value': endpoint,
                'dropdown':'endpoint'
            }
        }
    }
}

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'device'
}];

let i = 1;

if (typeof msg.limit_model !== 'undefined') {
    let devices = global.get('kernel.device', 'default');
    if (typeof devices === 'object') {
        for (const device in devices) {
            /* 0 = model, 1 = device */
            let split = device.split("|");
            if (msg.limit_model === split[0]) {
                msg.options[i++] = {
                    'label': split[1],
                    'value': split[1],
                    'dropdown':'device'
                }
            }
        }
    }
}

return msg;

msg.options = [{
    'label':'',
    'value':'',
    'dropdown':'link'
}];

let i = 1;

let links = global.get('kernel.endpoint', 'default');
if (typeof links === 'object') {
    for (const link in links) {
        /* 0 = equipment, 1 = component */
        let split = links[link].split("|");
        if (typeof msg.limit_component === 'undefined' || split[1].match((new RegExp('^(' + msg.limit_component + ')$'))) !== null) {
            if (typeof msg.limit_equipment === 'undefined' || split[0].match((new RegExp('^(' + msg.limit_equipment + ')$'))) !== null) {
                let name = msg.dictionary?.option_component[split[1]];
                msg.options[i++] = {
                    'label': name + ' (' + link + ')',
                    'value': link,
                    'dropdown':'link'
                }
            }
        }
    }
}
return msg;

msg.starttime = 0;
msg.stoptime = 0;

if (typeof msg.limit_plant === 'string' && msg.limit_plant !== '' && typeof msg.limit_team === 'string' && msg.limit_team != '') {
    let period = msg.limit_plant + '|' + msg.limit_team;
    let times = global.get('kernel.team["' + period + '"]', 'default');
    if (typeof times === 'string') {
        let split = times.split("|");
        msg.starttime = split[0];
        msg.stoptime = split[1];
    }
}

delete msg.limit_plant;
delete msg.limit_team;

return msg;

if (typeof msg.kernel?.equipment === 'string' && typeof msg.kernel?.component === 'string') {
    let reverse = global.get('kernel.reverse["' + msg.kernel.equipment + '|' + msg.kernel.component + '"]', 'default');
    if (typeof reverse === 'boolean' && reverse === true) {
        msg.kernel.value = msg.kernel.value === 0 ? 1 : 0;
    }
}

return msg;

