if (msg.kernel.model === 'opta') {

    if (msg.kernel.endpoint.match((new RegExp('(reset)$'))) !== null) {
        for (let rio = 0; rio < 8; rio++) {
            /* reset an input */
            if (msg.kernel.endpoint === ('i' + rio + 'reset')) {
                msg.topic = 'opta/' + msg.kernel.device + '/input/reset';
                msg.payload = rio;

                delete msg.kernel;

                return msg;
                /* reset an output */
            } else if (msg.kernel.endpoint === ('o' + rio + 'reset')) {
                msg.topic = 'opta/' + msg.kernel.device + '/output/reset';
                msg.payload = rio;

                delete msg.kernel;

                return msg;
            }
        }
    }

    /* command an output */
    if (msg.kernel.endpoint.match((new RegExp('^(o)'))) !== null) {
        for (let eio = 0; eio < 8; eio++) {
            if (msg.kernel.endpoint === ('o' + eio + 'state')) {
                msg.topic = 'opta/' + msg.kernel.device + '/output/set/' + eio;
                msg.payload = msg.kernel.value;

                delete msg.kernel;

                return msg;
